mapper.sql:
FROM tax_invoice ti
LEFT JOIN settlement_block sb ON sb.settle_id = ti.settle_block_id
LEFT JOIN block b ON b.block_id = sb.block_id
LEFT JOIN step st ON st.step_id = b.step_id
LEFT JOIN project p ON p.project_id = st.project_id AND p.deleted_at IS NULL
LEFT JOIN employee e ON e.user_id = ti.linked_by
WHERE ti.deleted_at IS NULL
AND ti.company_id = #{companyId}
AND ti.issued_no >= #{startDate}
AND ti.issued_no <= #{endDate}
AND ti.settle_block_id IS NULL
AND p.project_id = #{projectId}

    AND (ti.approval_no LIKE CONCAT('%', #{keyword}, '%') OR ti.buyer_name LIKE CONCAT('%', #{keyword}, '%'))

mapper.select:
SELECT ti.tax_id AS taxId, ti.issued_no AS issuedNo, ti.approval_no AS approvalNo, ti.type AS type, ti.buyer_name AS buyerName, ti.buyer_biz_no AS buyerBizNo, ti.supplier_biz_no AS supplierBizNo, ti.sub_biz_no AS subBizNo, ti.ceo_name AS ceoName, ti.item_name AS itemName, ti.supply_amount AS supplyAmount, ti.tax_amount AS taxAmount, ti.total_amount AS totalAmount, ti.memo AS memo, ti.source_type AS sourceType, p.project_id AS projectId, p.name AS projectName, sb.settle_id AS settleId, b.title AS roundName, ti.linked_by AS linkedBy, e.name AS linkedByName, ti.linked_at AS linkedAt, ti.is_excluded AS isExcluded, CASE WHEN ti.settle_block_id IS NULL THEN 'UNLINKED' WHEN sb.deleted_at IS NOT NULL OR b.deleted_at IS NOT NULL THEN 'LINK_BLOCK_DELETED' ELSE 'LINKED' END AS linkStatus
ORDER BY ti.issued_no ASC, ti.tax_id ASC ORDER BY ti.total_amount DESC, ti.tax_id DESC ORDER BY ti.issued_no DESC, ti.tax_id DESC
LIMIT #{size} OFFSET #{offset}
